var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var asks = Array.prototype.slice.call(root.querySelectorAll('.trm6-book-ladder-arow'));
var bids = Array.prototype.slice.call(root.querySelectorAll('.trm6-book-ladder-brow'));
var midEl = root.querySelector('.trm6-book-ladder-mv');
var sprEl = root.querySelector('.trm6-book-ladder-ms');
var tick = 0.5, mid = 64212.0;
var aq = [286, 214, 142, 64], bq = [72, 158, 205, 264];
function paint() {
  var all = aq.concat(bq), mx = 1, i;
  for (i = 0; i < all.length; i++) { if (all[i] > mx) mx = all[i]; }
  for (i = 0; i < asks.length; i++) {
    var ap = mid + tick * 0.5 + tick * (asks.length - 1 - i);
    asks[i].querySelector('.trm6-book-ladder-p').textContent = ap.toFixed(2);
    asks[i].querySelector('.trm6-book-ladder-q').textContent = aq[i];
    asks[i].querySelector('.trm6-book-ladder-bar').style.width = (6 + aq[i] / mx * 88) + '%';
  }
  for (i = 0; i < bids.length; i++) {
    var bp = mid - tick * 0.5 - tick * i;
    bids[i].querySelector('.trm6-book-ladder-p').textContent = bp.toFixed(2);
    bids[i].querySelector('.trm6-book-ladder-q').textContent = bq[i];
    bids[i].querySelector('.trm6-book-ladder-bar').style.width = (6 + bq[i] / mx * 88) + '%';
  }
  midEl.textContent = mid.toFixed(2);
  sprEl.textContent = 'SPRD ' + tick.toFixed(2);
}
function again(el, cls) {
  if (reduce || !el) return;
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
}
paint();
if (!reduce) {
  var beat = 0;
  var timer = setInterval(function () {
    beat++;
    if (beat % 9 === 0) {
      var up = Math.random() < 0.5;
      mid += up ? tick : -tick;
      if (up) { aq.push(40 + Math.round(Math.random() * 120)); aq.shift(); }
      else { bq.unshift(40 + Math.round(Math.random() * 120)); bq.pop(); }
      paint();
      again(midEl, up ? 'trm6-book-ladder-up' : 'trm6-book-ladder-dn');
      return;
    }
    var side = Math.random() < 0.5;
    var idx = Math.floor(Math.random() * 4);
    var arr = side ? aq : bq;
    var nv = Math.max(6, Math.round(arr[idx] * (0.6 + Math.random() * 0.85)));
    arr[idx] = Math.min(340, nv);
    paint();
    var row = (side ? asks : bids)[idx];
    again(row.querySelector('.trm6-book-ladder-bar').parentNode, 'trm6-book-ladder-fl');
  }, 380);
  if (root.__trm6bl) clearInterval(root.__trm6bl);
  root.__trm6bl = timer;
}

var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var body = root.querySelector('.trm6-fills-tape-body');
var cnt = root.querySelector('.trm6-fills-tape-cnt');
var vens = ['NSDQ', 'ARCA', 'EDGX', 'BATS', 'IEX', 'NSDQ', 'ARCA'];
var px = 178.43, prints = 14208, MAX = 8;
function pad(n, w) { var s = String(n); while (s.length < w) { s = '0' + s; } return s; }
function stamp() {
  var d = new Date();
  return pad(d.getHours(), 2) + ':' + pad(d.getMinutes(), 2) + ':' + pad(d.getSeconds(), 2) + '.' + pad(d.getMilliseconds(), 3);
}
function group(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function cell(cls, txt) {
  var s = document.createElement('span');
  s.className = 'trm6-fills-tape-' + cls;
  s.textContent = txt;
  return s;
}
function print() {
  var dark = Math.random() < 0.12;
  var buy = Math.random() < 0.5;
  var kind = dark ? 'dark' : (buy ? 'buy' : 'sell');
  var lot = Math.random() < 0.12 ? 1000 + Math.round(Math.random() * 8) * 500 : (1 + Math.round(Math.random() * 9)) * 100;
  px = Math.max(177.5, Math.min(179.4, px + (Math.random() - 0.48) * 0.02));
  var row = document.createElement('div');
  row.className = 'trm6-fills-tape-row trm6-fills-tape-' + kind + (lot >= 1000 ? ' trm6-fills-tape-blk' : '');
  row.appendChild(cell('tm', stamp()));
  row.appendChild(cell('sd', dark ? '·' : (buy ? 'B' : 'S')));
  row.appendChild(cell('px', px.toFixed(2)));
  row.appendChild(cell('qz', group(lot)));
  row.appendChild(cell('vn', dark ? 'DARK' : vens[Math.floor(Math.random() * vens.length)]));
  body.insertBefore(row, body.firstChild);
  while (body.children.length > MAX) { body.removeChild(body.lastChild); }
  prints++;
  cnt.textContent = group(prints) + ' PRN';
}
if (!reduce) {
  var loop = function () {
    print();
    root.__trm6ft = setTimeout(loop, 260 + Math.random() * 620);
  };
  if (root.__trm6ft) clearTimeout(root.__trm6ft);
  root.__trm6ft = setTimeout(loop, 400);
}

