js:
var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var rows = Array.prototype.slice.call(root.querySelectorAll('.trm6-pos-grid-body .trm6-pos-grid-row'));
var net = root.querySelector('.trm6-pos-grid-net');
var netPnl = net.querySelector('.trm6-pos-grid-pnl');
var netGrs = net.querySelector('.trm6-pos-grid-lst');
var book = [
  { qty: 2400, avg: 214.12, last: 214.12 },
  { qty: -1100, avg: 402.55, last: 402.55 },
  { qty: 800, avg: 246.90, last: 246.90 },
  { qty: -450, avg: 183.27, last: 183.27 },
  { qty: 1250, avg: 512.40, last: 512.40 }
];
for (var s = 0; s < book.length; s++) {
  book[s].last = book[s].avg * (1 + (Math.random() - 0.45) * 0.012);
}
function money(v) {
  var a = Math.abs(v), sgn = v < 0 ? '-' : '+';
  if (a >= 1000000) return sgn + (a / 1000000).toFixed(2) + 'M';
  if (a >= 1000) return sgn + (a / 1000).toFixed(1) + 'K';
  return sgn + a.toFixed(0);
}
function paintRow(i, dir) {
  var p = book[i], r = rows[i];
  var pnl = (p.last - p.avg) * p.qty;
  var lst = r.querySelector('.trm6-pos-grid-lst');
  var pn = r.querySelector('.trm6-pos-grid-pnl');
  lst.textContent = p.last.toFixed(2);
  pn.textContent = money(pnl);
  pn.className = 'trm6-pos-grid-pnl ' + (pnl >= 0 ? 'trm6-pos-grid-gain' : 'trm6-pos-grid-loss');
  if (dir && !reduce) {
    var cls = dir > 0 ? 'trm6-pos-grid-tu' : 'trm6-pos-grid-td';
    lst.classList.remove('trm6-pos-grid-tu', 'trm6-pos-grid-td');
    void lst.offsetWidth;
    lst.classList.add(cls);
  }
}
function paintNet() {
  var tot = 0, grs = 0;
  for (var i = 0; i < book.length; i++) {
    tot += (book[i].last - book[i].avg) * book[i].qty;
    grs += Math.abs(book[i].qty) * book[i].last;
  }
  netPnl.textContent = money(tot);
  netPnl.className = 'trm6-pos-grid-pnl ' + (tot >= 0 ? 'trm6-pos-grid-gain' : 'trm6-pos-grid-loss');
  netGrs.textContent = (grs / 1000000).toFixed(2) + 'M';
}
for (var k = 0; k < book.length; k++) { paintRow(k, 0); }
paintNet();
if (!reduce) {
  if (root.__trm6pg) clearInterval(root.__trm6pg);
  root.__trm6pg = setInterval(function () {
    var i = Math.floor(Math.random() * book.length);
    var step = book[i].avg * 0.0009 * (Math.random() * 2 - 1);
    var dir = step >= 0 ? 1 : -1;
    book[i].last = Math.max(book[i].avg * 0.9, book[i].last + step);
    paintRow(i, dir);
    paintNet();
  }, 620);
}

