js:
var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var inEl = root.querySelector('.trm6-order-cmd-in');
var ackEl = root.querySelector('.trm6-order-cmd-ack');
var hist = Array.prototype.slice.call(root.querySelectorAll('.trm6-order-cmd-h'));
var cells = Array.prototype.slice.call(root.querySelectorAll('.trm6-order-cmd-t'));
var cmds = [
  ['BUY', '2500', 'AAPL', 'LMT', '214.30'],
  ['SELL', '800', 'NVDA', 'MKT', '—'],
  ['BUY', '15000', 'F', 'VWAP', '11.84'],
  ['SELL', '1200', 'MSFT', 'LMT', '402.05']
];
var ci = 0;
function render(tokens, chars) {
  while (inEl.firstChild) { inEl.removeChild(inEl.firstChild); }
  var used = 0;
  for (var i = 0; i < tokens.length; i++) {
    if (used >= chars) break;
    var piece = tokens[i].slice(0, chars - used);
    var sp = document.createElement('span');
    sp.className = 'trm6-order-cmd-tk' + i;
    sp.textContent = piece;
    inEl.appendChild(sp);
    used += piece.length;
    if (used >= chars) break;
    if (i < tokens.length - 1) { inEl.appendChild(document.createTextNode(' ')); used++; }
  }
}
function setCell(i, txt) {
  cells[i].textContent = txt;
  cells[i].className = 'trm6-order-cmd-t trm6-order-cmd-t' + i + ' trm6-order-cmd-set';
}
function resetCells() {
  for (var i = 0; i < cells.length; i++) {
    cells[i].textContent = '·';
    cells[i].className = 'trm6-order-cmd-t trm6-order-cmd-t' + i;
  }
}
function hex() {
  var s = '', d = '0123456789ABCDEF';
  for (var i = 0; i < 4; i++) { s += d[Math.floor(Math.random() * 16)]; }
  return s;
}
function pushHist(id, tokens) {
  hist[0].textContent = hist[1].textContent;
  hist[1].textContent = '✓ 0x' + id + ' ' + tokens.join(' ');
}
function ack(id, ven) {
  ackEl.textContent = '✓ ACK 0x' + id + ' ROUTED ' + ven + ' · WORKING';
  ackEl.className = 'trm6-order-cmd-ack trm6-order-cmd-live';
  if (!reduce) {
    ackEl.classList.remove('trm6-order-cmd-pop');
    void ackEl.offsetWidth;
    ackEl.classList.add('trm6-order-cmd-pop');
  }
}
if (reduce) {
  render(cmds[0], 999);
  for (var q = 0; q < cmds[0].length; q++) { setCell(q, cmds[0][q]); }
  ack('7F2C', 'NSDQ');
} else {
  var run = function () {
    var tokens = cmds[ci % cmds.length];
    ci++;
    var line = tokens.join(' ');
    var n = 0, filled = 0;
    resetCells();
    ackEl.textContent = 'parsing…';
    ackEl.className = 'trm6-order-cmd-ack';
    render(tokens, 0);
    var type = setInterval(function () {
      n++;
      render(tokens, n);
      var done = 0, acc = 0;
      for (var i = 0; i < tokens.length; i++) {
        acc += tokens[i].length;
        if (n >= acc) { done = i + 1; }
        acc++;
      }
      if (n >= line.length) { done = tokens.length; }
      while (filled < done) { setCell(filled, tokens[filled]); filled++; }
      if (n >= line.length) {
        clearInterval(type);
        root.__trm6oc = setTimeout(function () {
          var id = hex();
          ack(id, ['NSDQ', 'ARCA', 'EDGX', 'BATS'][Math.floor(Math.random() * 4)]);
          root.__trm6oc = setTimeout(function () { pushHist(id, tokens); run(); }, 2400);
        }, 320);
      }
    }, 62);
    root.__trm6ocType = type;
  };
  if (root.__trm6oc) clearTimeout(root.__trm6oc);
  if (root.__trm6ocType) clearInterval(root.__trm6ocType);
  run();
}

