var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var rows = Array.prototype.slice.call(root.querySelectorAll('.trm6-mkt-matrix-row'));
rows.shift();
var tickEl = root.querySelector('.trm6-mkt-matrix-tick');
var updEl = root.querySelector('.trm6-mkt-matrix-upd');
var grid = [];
for (var r = 0; r < rows.length; r++) {
  var cs = rows[r].querySelectorAll('.trm6-mkt-matrix-cell');
  var vals = [];
  for (var c = 0; c < cs.length; c++) { vals.push(parseFloat(cs[c].textContent)); }
  grid.push({ els: cs, v: vals });
}
var updates = 0;
function pad(n) { return n < 10 ? '0' + n : String(n); }
function clock() {
  var d = new Date();
  tickEl.textContent = 'TICK ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
function bump() {
  var r = Math.floor(Math.random() * grid.length);
  var c = Math.floor(Math.random() * grid[r].els.length);
  var cur = grid[r].v[c];
  var step = (Math.abs(cur) * 0.012 + 0.05) * (Math.random() * 2 - 1);
  var nv = cur + step;
  grid[r].v[c] = nv;
  var el = grid[r].els[c];
  el.textContent = nv.toFixed(1);
