}
clock();
if (!reduce) {
  if (root.__trm6mm) clearInterval(root.__trm6mm);
  root.__trm6mm = setInterval(function () {
    var n = 1 + Math.floor(Math.random() * 2);
    for (var i = 0; i < n; i++) { bump(); }
    clock();
  }, 620);
}

