var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var aEl = root.querySelector('.trm6-spread-mon-pa');
var bEl = root.querySelector('.trm6-spread-mon-pb');
var sEl = root.querySelector('.trm6-spread-mon-sv');
var zEl = root.querySelector('.trm6-spread-mon-zv');
var spEl = root.querySelector('.trm6-spread-mon-spark');
var mkEl = root.querySelector('.trm6-spread-mon-mark');
var wvEl = root.querySelector('.trm6-spread-mon-wv');
var BAR = '▁▂▃▄▅▆▇█';
var a = 71.42, b = 71.08, N = 40;
var hist = [];
for (var i = 0; i < N; i++) { hist.push(0.34 + Math.sin(i / 3.6) * 0.16 + (Math.random() - 0.5) * 0.05); }
function draw() {
  var lo = Infinity, hi = -Infinity, i, m = 0, sd = 0;
  for (i = 0; i < hist.length; i++) {
    if (hist[i] < lo) lo = hist[i];
    if (hist[i] > hi) hi = hist[i];
    m += hist[i];
  }
  m /= hist.length;
  for (i = 0; i < hist.length; i++) { sd += (hist[i] - m) * (hist[i] - m); }
  sd = Math.sqrt(sd / hist.length) || 0.0001;
  var rng = (hi - lo) || 0.0001, s = '';
  for (i = 0; i < hist.length; i++) {
    s += BAR[Math.min(7, Math.max(0, Math.round((hist[i] - lo) / rng * 7)))];
  }
  spEl.textContent = s;
  var cur = hist[hist.length - 1];
  var z = (cur - m) / sd;
  aEl.textContent = a.toFixed(2);
  bEl.textContent = b.toFixed(2);
  sEl.textContent = (cur >= 0 ? '+' : '') + cur.toFixed(3);
  zEl.textContent = (z >= 0 ? '+' : '') + z.toFixed(2);
  var hot = Math.abs(z) >= 1.8;
  zEl.className = 'trm6-spread-mon-zv' + (hot ? ' trm6-spread-mon-hot' : '');
  mkEl.className = 'trm6-spread-mon-mark' + (hot ? ' trm6-spread-mon-mhot' : '');
  var pos = Math.max(0, Math.min(100, 50 + (z / 2) * 50));
  mkEl.style.left = 'calc(' + pos + '% - 1px)';
  wvEl.textContent = 'HI ' + (hi >= 0 ? '+' : '') + hi.toFixed(2) + '  LO ' + (lo >= 0 ? '+' : '') + lo.toFixed(2) + '  σ ' + sd.toFixed(3);
}
function step() {
  a = Math.max(69, Math.min(74, a + (Math.random() - 0.5) * 0.06));
  b = Math.max(69, Math.min(74, b + (Math.random() - 0.5) * 0.055));
  hist.push(a - b);
  if (hist.length > N) hist.shift();
  draw();
}
draw();
if (!reduce) {
  if (root.__trm6sm) clearInterval(root.__trm6sm);
  root.__trm6sm = setInterval(step, 700);
}

