var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var body = root.querySelector('.trm6-exec-log-body');
var rate = root.querySelector('.trm6-exec-log-rt');
var syms = ['MSFT', 'AAPL', 'NVDA', 'AMZN', 'META', 'TSLA'];
var vens = ['NSDQ', 'ARCA', 'EDGX', 'BATS'];
var oid = 8843, MAX = 8, msgs = 0, live = null;
function pad(n, w) { var s = String(n); while (s.length < w) { s = '0' + s; } return s; }
function stamp() {
  var d = new Date();
  return pad(d.getHours(), 2) + ':' + pad(d.getMinutes(), 2) + ':' + pad(d.getSeconds(), 2) + '.' + pad(d.getMilliseconds(), 3);
}
function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
function emit(kind, tag, msg) {
  var row = document.createElement('div');
  row.className = 'trm6-exec-log-row trm6-exec-log-' + kind;
  var t = document.createElement('span');
  t.className = 'trm6-exec-log-tm';
  t.textContent = stamp();
  var g = document.createElement('span');
  g.className = 'trm6-exec-log-tg';
  g.textContent = tag;
  var m = document.createElement('span');
  m.className = 'trm6-exec-log-ms';
  m.textContent = msg;
  row.appendChild(t);
  row.appendChild(g);
  row.appendChild(m);
  body.appendChild(row);
  while (body.children.length > MAX) { body.removeChild(body.firstChild); }
  msgs++;
}
function beat() {
  var r = Math.random();
  if (!live) {
    oid++;
    var q = (1 + Math.floor(Math.random() * 9)) * 100;
    live = { id: oid, sym: pick(syms), qty: q, left: q, px: 100 + Math.random() * 320, acked: false };
    emit('snd', 'SND', live.id + ' ' + (Math.random() < 0.5 ? 'BUY' : 'SEL') + ' ' + live.qty + ' ' + live.sym + ' LMT ' + live.px.toFixed(2));
  } else if (!live.acked) {
    live.acked = true;
    emit('ack', 'ACK', live.id + ' VEN=' + pick(vens) + ' SEQ ' + (20000 + Math.floor(Math.random() * 900)));
  } else if (r < 0.08) {
    emit('cxl', 'CXL', live.id + ' RSN=' + pick(['USER', 'TIMEOUT', 'REPLACE']));
    live = null;
  } else if (r < 0.13) {
    oid++;
    emit('rej', 'REJ', oid + ' RSN=' + pick(['RISK:MAXNOT', 'RISK:SSHORT', 'VEN:HALT']));
  } else {
    var part = Math.max(100, Math.round(live.left * (0.3 + Math.random() * 0.7) / 100) * 100);
    if (part > live.left) part = live.left;
    live.left -= part;
    emit('fil', 'FIL', live.id + ' ' + part + '@' + (live.px - 0.01).toFixed(2) + ' LVS ' + live.left);
    if (live.left <= 0) live = null;
  }
  rate.textContent = (2 + Math.floor(Math.random() * 7)) + ' msg/s';
}
if (!reduce) {
  var loop = function () {
    beat();
    root.__trm6el = setTimeout(loop, 320 + Math.random() * 700);
  };
  if (root.__trm6el) clearTimeout(root.__trm6el);
  root.__trm6el = setTimeout(loop, 500);
}

