var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var rows = Array.prototype.slice.call(root.querySelectorAll('.trm6-risk-limits-row'));
var bc = root.querySelector('.trm6-risk-limits-bc');
var chk = root.querySelector('.trm6-risk-limits-chk');
var W = 14;
var lim = [
  { used: 4.20, cap: 6.00, u: 'M', dp: 2 },
  { used: 18.7, cap: 20.0, u: 'M', dp: 1 },
  { used: 812, cap: 750, u: 'K', dp: 0 },
  { used: 142, cap: 500, u: 'K', dp: 0, neg: 1 },
  { used: 3.1, cap: 8.0, u: '%', dp: 1 },
  { used: 61, cap: 120, u: 'K', dp: 0 }
];
function pad(n) { return n < 10 ? '0' + n : String(n); }
function bars(ch, n) { var s = '', i; for (i = 0; i < n; i++) { s += ch; } return s; }
function paint() {
  var breaches = 0;
  for (var i = 0; i < rows.length; i++) {
    var L = lim[i], r = rows[i];
    var p = L.used / L.cap;
    var state = p >= 1 ? 'brch' : (p >= 0.85 ? 'warn' : 'ok');
    if (state === 'brch') breaches++;
    r.className = 'trm6-risk-limits-row' + (state === 'ok' ? '' : ' trm6-risk-limits-' + state);
    var v = (L.neg ? '-' : '') + L.used.toFixed(L.dp) + (L.u === '%' ? '%' : L.u);
    r.querySelector('.trm6-risk-limits-us').textContent = v;
    r.querySelector('.trm6-risk-limits-lm').textContent = '/' + (L.neg ? '-' : '') + L.cap.toFixed(L.dp) + (L.u === '%' ? '%' : L.u);
    var f = Math.max(0, Math.min(W, Math.round(p * W)));
    r.querySelector('.trm6-risk-limits-mf').textContent = bars('█', f);
    r.querySelector('.trm6-risk-limits-me').textContent = bars('░', W - f);
    r.querySelector('.trm6-risk-limits-pc').textContent = Math.round(p * 100) + '%';
    r.querySelector('.trm6-risk-limits-st').textContent = state === 'brch' ? 'BRCH' : (state === 'warn' ? 'WRN' : 'OK');
  }
  bc.textContent = 'BREACH ×' + breaches;
  bc.className = 'trm6-risk-limits-bc' + (breaches ? ' trm6-risk-limits-hot' : '');
  var d = new Date();
  chk.textContent = 'CHK ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
paint();
if (!reduce) {
  if (root.__trm6rl) clearInterval(root.__trm6rl);
  root.__trm6rl = setInterval(function () {
    var i = Math.floor(Math.random() * lim.length);
    var L = lim[i];
    var drift = L.cap * 0.035 * (Math.random() * 2 - 1);
    L.used = Math.max(L.cap * 0.05, Math.min(L.cap * 1.22, L.used + drift));
    paint();
  }, 900);
}
